"""Provenance-aware writing agent.""" def verse(i,text,source): return f'सूत्र {i:06d}: {text}
स्रोत: {source}
स्थिति: स्रोत-आधारित लेखन-प्रारूप; स्वतंत्र सत्यापन अपेक्षित।' def paper(i,q,source): return f'# Research Paper Draft {i:03d}

## Research question
{q}

## Source
{source}

## Status
Draft only; independent review required.
'
